# Generated by Rimworld-Release-Admin/scripts/generate-publish-workflow.sh (template: publish-workflow/mod-tests/Test-Mod.ps1). Never edit this copy: regenerate.
# What only this mod asserts is one script per rule, Tests/Rule-<WhatItChecks>.ps1, each declared in scripts/LOCAL_SCRIPTS.md; this script runs them last.
param([string]$ModPath = (Join-Path $PSScriptRoot '../Mod'))

# Offline suite: the shared checks run first, then every Tests/Rule-*.ps1 of the mod, sorted by name, one test per script.
# Shared scripts are read from ../../scripts (protocols checkout) then .github/scripts (copies made by CI/CD, docs/CICD.md); neither
# found is a failure, never a silent skip. Check-DefRefs, Check-PatchTargets and Check-ConfigErrors need the game or the Workshop:
# CI/CD does not copy them to .github/scripts, so on the GitHub runner they SKIP, loudly, and every local run plays them.
# A rule script takes -ModRoot and -SharedDir (the shared folder found below, where it dot-sources lib/ModDefs.ps1 when it needs the def
# index), prints its findings and exits 1 on any: the exit code decides, its output is the detail of a failure.
$ErrorActionPreference = 'Stop'
$ModPath = (Resolve-Path -LiteralPath $ModPath).Path
$ModRoot = Split-Path -Parent $ModPath
$SharedDir = @((Join-Path $ModRoot '../scripts'), (Join-Path $ModRoot '.github/scripts')) | Where-Object { Test-Path -LiteralPath (Join-Path $_ 'lib/TestRunner.ps1') } | Select-Object -First 1
if (-not $SharedDir) { Write-Host 'FAIL shared scripts not found (looked in ../scripts and .github/scripts of the mod): the generic checks did NOT run' -ForegroundColor Red; exit 1 }
$SharedDir = (Resolve-Path -LiteralPath $SharedDir).Path
. (Join-Path $SharedDir 'lib/TestRunner.ps1')

# One script as one test: the exit code decides, its output is the detail of a failure.
function Invoke-Script([string]$Path, [string[]]$Arguments) {
    $out = @(& powershell -NoProfile -ExecutionPolicy Bypass -File $Path @Arguments 2>&1 | ForEach-Object { "$_" })
    if ($LASTEXITCODE -ne 0) { $out | Where-Object { $_ -match '\S' } | Select-Object -Last 15 }
}
function Invoke-Shared([string]$Script, [string[]]$Arguments) {
    if (-not (Test-Path -LiteralPath (Join-Path $SharedDir $Script))) { throw "$Script not found in $SharedDir" }
    Invoke-Script (Join-Path $SharedDir $Script) $Arguments
}
# A check that needs the game or the Workshop: absent from the shared folder (the runner) = SKIP, not pass.
function Invoke-SharedOrSkip([string]$Script, [string[]]$Arguments) {
    if (-not (Test-Path -LiteralPath (Join-Path $SharedDir $Script))) { Write-Host "WARNING $Script not in $SharedDir (needs the game or the Workshop): SKIPPED, not passed" -ForegroundColor Yellow; return 'skip' }
    $problems = @(Invoke-Shared $Script $Arguments)
    if ($problems.Count) { throw ($problems -join [Environment]::NewLine) }
    return $true
}

# A mod rule that runs a shared check itself, with arguments this skeleton cannot know (Check-DefRefs -AlsoScan for a mod that depends on
# another), declares it in a comment line of its own file, `# Replaces-Shared: DefRefs ConfigErrors`. The skeleton then does not run that
# check alone (it would fail on every reference into the dependency) and says which rule covers it. Only DefRefs and ConfigErrors are replaceable.
$Replaced = @{}
foreach ($rule in @(Get-ChildItem -LiteralPath $PSScriptRoot -Filter 'Rule-*.ps1' -File | Sort-Object Name)) {
    foreach ($line in @(Get-Content -LiteralPath $rule.FullName -TotalCount 15)) {
        if ($line -match '^\s*#\s*Replaces-Shared:\s*(.+)$') { foreach ($n in ($Matches[1] -split '[\s,]+' | Where-Object { $_ })) { if ($n -in 'DefRefs', 'ConfigErrors') { $Replaced[$n] = $rule.Name } } }
    }
}
function Test-Covered([string]$Name) {
    if ($Replaced.ContainsKey($Name)) { Write-Host "Shared: Check-$Name is run by $($Replaced[$Name]) (Replaces-Shared)" -ForegroundColor Cyan; return $true }
    return $false
}

It 'Shared: XML well formed, unique defNames, About.xml, Preview and icon (Check-ModBasics)' { Invoke-Shared 'Check-ModBasics.ps1' '-ModRoot', $ModRoot }
if (-not (Test-Covered 'DefRefs')) { Test-That 'Shared: every def reference and inheritance parent resolves (Check-DefRefs)' { Invoke-SharedOrSkip 'Check-DefRefs.ps1' '-ModPath', $ModPath, '-Brief' } }
It 'Shared: every texture path resolves to a shipped file (Check-Textures)' { Invoke-Shared 'Check-Textures.ps1' '-ModRoot', $ModRoot }
Test-That 'Shared: every patch target still exists in the installed mod (Check-PatchTargets)' { Invoke-SharedOrSkip 'Check-PatchTargets.ps1' '-ModRoot', $ModRoot }
if (-not (Test-Covered 'ConfigErrors')) { Test-That 'Shared: no config error of the game (Check-ConfigErrors)' { Invoke-SharedOrSkip 'Check-ConfigErrors.ps1' '-ModPath', $ModPath } }

# The mod's own rules: one test per script, in name order.
foreach ($rule in @(Get-ChildItem -LiteralPath $PSScriptRoot -Filter 'Rule-*.ps1' -File | Sort-Object Name)) {
    $path = $rule.FullName
    It "Rule: $($rule.Name)" { Invoke-Script $path '-ModRoot', $ModRoot, '-SharedDir', $SharedDir }
}
Complete-Tests
